    "text": "2010-yillar oxiridan O‘zbekistonda go‘sht narxlari umumiy inflyatsiyadan tezroq o‘sdi. Talab va taklif modeli bu hodisani tushuntiradi: Talab tomonida: aholining yiliga qariyb 1,5–2 foizga o‘sishi, real daromadlarning oshishi (go‘sht – normal tovar), mehnat muhojirlarining pul o‘tkazmalari hisobiga iste’molning kengayishi, to‘y va marosimlar bilan bog‘liq mavsumiy talab – talab chizig‘i o‘ngga siljidi. Taklif tomonida: yem-xashak va ozuqa narxlarining oshishi, yaylovlarning cheklanganligi, chorvachilikda unumdorlikning pastligi taklifning sekin o‘sishiga sabab bo‘ldi. Natija: talab taklifdan tezroq o‘sgani sababli muvozanat narxi oshdi. Davlat choralari: narxni ma’muriy cheklash (bu taqchillikka olib kelardi) o‘rniga taklifni oshirishga qaratilgan choralar ko‘rildi – chorva mollari va go‘sht importiga bojxona imtiyozlari, naslli chorva sotib olishga imtiyozli kreditlar, yem-xashak ishlab chiqarishni rag‘batlantirish. Bu taklif chizig‘ini o‘ngga siljitishga qaratilgan, iqtisodiy jihatdan to‘g‘ri yondashuv. Topshiriq: so‘nggi bir yilda biror oziq-ovqat mahsuloti narxining o‘zgarishini uch bosqichli usul bilan tahlil qiling.",
