    "text": "O‘zbekistonda aholi uchun elektr energiyasi tariflari 2024-yildan boshlab iste’mol hajmiga bog‘liq bloklar bo‘yicha belgilanmoqda – bu ikkinchi darajali narx differensiatsiyasining ijtimoiy yo‘naltirilgan shakli. 2025-yil 1-maydan oyiga 200 kVt·soatgacha bo‘lgan iste’mol uchun tarif 450 so‘mdan 600 so‘mga oshirildi, 201–500 kVt·soat bloki uchun esa 1000 so‘mdan 800 so‘mga tushirildi (12.7-rasm). Yuqoriroq iste’mol bloklari uchun esa yuqoriroq stavkalar saqlanadi. Bundan tashqari, gaz va elektr narxlari har yili 1-maydan inflyatsiya darajasida, ammo 10 foizdan oshmagan holda indeksatsiya qilinishi belgilandi. Iqtisodiy mantiq: 1) birinchi blok – aholining asosiy ehtiyojlari uchun «ijtimoiy norma» bo‘lib, uning narxi tannarxdan pastroq; 2) yuqori bloklar narxi tannarxga yaqin yoki undan yuqori – yuqori iste’molchilar (katta uylar, elektr isitish) o‘z xarajatlarini qoplaydi va qisman kam iste’molchilarni subsidiyalaydi; 3) o‘suvchi bloklar energiyani tejashga rag‘batlantiradi. Kamchilik: katta oilalar (ko‘p a’zoli xonadonlar) kambag‘al bo‘lsa ham yuqori blokka tushib qolishi mumkin – shuning uchun ijtimoiy reestrdagi oilalarga qo‘shimcha kompensatsiyalar qo‘llanadi.",
