     "Davlatning monopoliyaga nisbatan siyosati to‘rt yo‘nalishga ega: raqobatni himoya qilish (antimonopol qonunlar), narxlarni tartibga solish, davlat mulki va hech narsa qilmaslik.",
     "Monopoliyaga to‘g‘ri belgilangan narx shifti sof yo‘qotishni kamaytiradi va hajmni samarali darajaga yaqinlashtiradi.",
