    "text": "O‘zbekistonda eng kam oylik ish haqi (EKIH) Prezident farmonlari bilan belgilanadi va muntazam oshirib boriladi (14.6-rasm). 2025-yil 1-avgustdan EKIH 1 271 000 so‘m, bazaviy hisoblash miqdori (BHM) 412 000 so‘m qilib belgilandi. 2020-yildagi 679 ming so‘mga nisbatan EKIH qariyb 1,9 baravar oshdi. Shu bilan birga, 2025-yilda respublika bo‘yicha o‘rtacha nominal ish haqi 6,4 mln so‘m atrofida bo‘ldi – ya’ni EKIH o‘rtacha ish haqining taxminan 20 foizini tashkil etadi. Xalqaro taqqoslash uchun: OECD mamlakatlarida minimal ish haqi odatda mediana ish haqining 40–60 foizi atrofida. Iqtisodiy talqin: O‘zbekistonda EKIH o‘rtacha ish haqiga nisbatan past bo‘lgani uchun u ko‘pchilik tarmoqlar uchun «bog‘lovchi» cheklov emas – ishsizlikka sezilarli ta’sir qilmaydi. Shu bilan birga, EKIH ko‘plab ijtimoiy to‘lovlar (nafaqalar, jarimalar) uchun hisob birligi vazifasini bajargan; shuning uchun hisob-kitoblarda BHM ajratib olindi. Muhim muammo – norasmiy sektor: band aholining uchdan bir qismi norasmiy ishlaydi va EKIH ularga amalda tatbiq etilmaydi.",
