    "text": "O‘zbekiston Respublikasi Konstitutsiyasiga ko‘ra yer, yer osti boyliklari, suv, o‘simlik va hayvonot dunyosi hamda boshqa tabiiy zaxiralar umummilliy boylik bo‘lib, ulardan oqilona foydalanish zarur va ular davlat muhofazasidadir. Qishloq xo‘jaligiga mo‘ljallangan yerlar davlat mulki hisoblanadi va fermer xo‘jaliklari, klasterlar va boshqa subyektlarga uzoq muddatli ijaraga (odatda 30 yildan 49 yilgacha) beriladi. So‘nggi yillardagi asosiy islohotlar: 1) qishloq xo‘jaligiga mo‘ljallanmagan yer uchastkalarini xususiylashtirish – 2021-yilda qabul qilingan qonun bilan yuridik va jismoniy shaxslarga ular foydalanayotgan noqishloq xo‘jalik yer uchastkalarini (uy-joy, savdo, sanoat ob’ektlari ostidagi yerlar) xususiy mulk sifatida sotib olish imkoniyati yaratildi; 2) yer uchastkalarini elektron auksion orqali berish – yerga bo‘lgan huquqlar «E-auksion» elektron savdo platformasi orqali ochiq tanlov asosida beriladi; bu korrupsiya xavfini kamaytiradi va yerning haqiqiy bozor qiymatini aniqlashga yordam beradi; 3) paxta va g‘alla yetishtirishda majburiy davlat buyurtmasining bekor qilinishi (2020-yil) – fermerlar mahsulotni erkin narxlarda sotish huquqiga ega bo‘ldi; 4) yerdan foydalanish samaradorligini nazorat qilish – yerdan maqsadsiz foydalanish va unumdorlikni pasaytirganlik uchun ijara shartnomasini bekor qilish mexanizmlari; 5) yerni hisobga olish va kadastr tizimini raqamlashti",
