    "instruction": "Vaziyatni o'qing va mavzudagi tushunchalar asosida tahlil qiling.",
    "text": "O‘zbekistonda 2017-yildan boshlab qishloq xo‘jaligida klaster tizimi joriy etildi: paxta-to‘qimachilik, g‘alla, meva-sabzavot, chorvachilik klasterlari. Klaster – xomashyo yetishtirishdan tortib qayta ishlash va eksportgacha bo‘lgan zanjirni yagona tashkiliy tizimga birlashtiruvchi tuzilma. Tranzaksiya xarajatlari nuqtai nazaridan klaster – gibrid shakl: klaster fermerlar bilan uzoq muddatli shartnomalar tuzadi, ularni urug‘, o‘g‘it, texnika va kreditlar bilan ta’minlaydi, hosilni kafolatlangan narxda sotib oladi. Bu: 1) fermerning xaridor izlash va narx bo‘yicha muzokara xarajatlarini kamaytiradi; 2) sifatni nazorat qilish (o‘lchash xarajatlari) imkonini beradi; 3) qayta ishlash korxonasiga xomashyo ta’minoti barqarorligini kafolatlaydi (spetsifik aktivlar – yigiruv fabrikasi – himoyalanadi). Muammolar: fermerlar klasterga bog‘lanib qolib, muzokara kuchini yo‘qotishi mumkin (monopsoniya, 14-bob); narxlar va shartnoma shartlari bo‘yicha nizolar yuzaga kelgan. Shuning uchun fermerlar huquqlarini himoya qilish va klasterlar o‘rtasida raqobatni rivojlantirish muhim vazifa hisoblanadi.",
