    "text": "O‘zbekiston energetika sektorida keng ko‘lamli «yashil» transformatsiyani amalga oshirmoqda. Mamlakat elektr energiyasining asosiy qismi tabiiy gaz hisobiga ishlab chiqariladi; qayta tiklanuvchi energiya manbalarining ulushini 2030-yilga borib keskin oshirish maqsad qilingan. Quyosh va shamol elektr stansiyalari xalqaro raqobatli auksionlar orqali xorijiy investorlar (Birlashgan Arab Amirliklari, Saudiya Arabistoni, Xitoy kompaniyalari) bilan davlat-xususiy sheriklik asosida qurilmoqda. Tashqi samaralar nazariyasi nuqtai nazaridan bu siyosat ikki vazifani hal qiladi: 1) tabiiy gazni yoqish bilan bog‘liq salbiy tashqi samaralarni (havo ifloslanishi, CO2) kamaytiradi; 2) gazni eksport qilish yoki kimyo sanoatida yuqori qo‘shilgan qiymatli mahsulotlarga aylantirish imkonini beradi. Shu bilan birga, 12-bobda ko‘rganimizdek, elektr energiyasi tariflari uzoq vaqt tannarxdan past bo‘lib kelgan – bu energiyani isrof qilishni rag‘batlantirgan va uning haqiqiy ijtimoiy xarajatini (shu jumladan ekologik xarajatni) aks ettirmagan. Tariflarni bosqichma-bosqich iqtisodiy asoslangan darajaga yetkazish va kam ta’minlangan oilalarni maqsadli himoya qilish – Pigu tamoyiliga yaqin yondashuv.",
